import{_ as s,o as i,c as a,a2 as t}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Build from source","description":"","frontmatter":{},"headers":[],"relativePath":"install-source.md","filePath":"install-source.md"}'),n={name:"install-source.md"};function o(l,e,r,d,h,p){return i(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="build-from-source" tabindex="-1">Build from source <a class="header-anchor" href="#build-from-source" aria-label="Permalink to &quot;Build from source&quot;">​</a></h1><p>Use this route for current development code. For a packaged install, use <a href="./install-fedora">Fedora&#39;s COPR packages</a> or the <a href="./install-debian">Debian/Ubuntu downloads</a>.</p><p>The build goes into <code>./install</code> inside your checkout. Keep the checkout there if you register it as a login session.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>This is a native source build. You still need a C/C++ toolchain, Python 3.11 or newer, Meson, Ninja, Git, Just and the base development libraries for GNOME. The private build supplies GLib, GJS, Wayland, Wayland protocols, libinput, mtdev, Lua, gnome-desktop and the PipeWire client libraries. Other development libraries must already be installed on the host.</p><p>Fedora, Arch, Debian/Ubuntu and openSUSE use the same private build path. The required library versions are checked during the build. If a base dependency does not meet the minimum version, the build stops and reports it without changing host packages.</p><h2 id="_1-get-the-source" tabindex="-1">1. Get the source <a class="header-anchor" href="#_1-get-the-source" aria-label="Permalink to &quot;1. Get the source&quot;">​</a></h2><p>Install Git with your distribution&#39;s package manager, then:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/kierandrewett/gnoblin.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gnoblin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build.sh</span></span></code></pre></div><p>The script builds pinned dependency versions in <code>./install/deps</code>, then builds Mutter, GNOME Shell and the Gnoblin session in <code>./install</code>. It never calls your system package manager. Run it as your normal user.</p><p>The dependency sources and checksums are in <code>build-dependencies.json</code>. Completed dependency builds are reused. Settings and the patched portal remain <a href="./source-development#optional-components">optional builds</a>.</p><h2 id="_2-try-it-in-a-window" tabindex="-1">2. Try it in a window <a class="header-anchor" href="#_2-try-it-in-a-window" aria-label="Permalink to &quot;2. Try it in a window&quot;">​</a></h2><p>From an existing Wayland desktop:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview</span></span></code></pre></div><p>A nested desktop and terminal open. Launch your layer-shell client from that terminal. Close the terminal to end the test. See <a href="./devkit">Devkit</a> for help.</p><h2 id="login-session" tabindex="-1">3. Add a login session <a class="header-anchor" href="#login-session" aria-label="Permalink to &quot;3. Add a login session {#login-session}&quot;">​</a></h2><p>After the build and nested test succeed:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GNOBLIN_PREFIX</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$PWD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/install&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> register-session</span></span></code></pre></div><p>Run the <code>sudo install</code> commands it prints. Then <a href="./bring-your-own-shell">install a shell</a>, log out and select <strong>Gnoblin</strong>.</p><p>Registration only adds session files; it does not build a missing runtime.</p><h2 id="build-options" tabindex="-1">Build options <a class="header-anchor" href="#build-options" aria-label="Permalink to &quot;Build options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>./build.sh</code></td><td>Build private dependencies, then Gnoblin</td></tr><tr><td><code>./build.sh --deps-only</code></td><td>Build only the private dependencies</td></tr><tr><td><code>./build.sh --no-deps</code></td><td>Reuse dependencies and rebuild Gnoblin</td></tr><tr><td><code>./build.sh --dry-run</code></td><td>Show what will be built</td></tr></tbody></table><h2 id="how-gnome-stays-separate" tabindex="-1">How GNOME stays separate <a class="header-anchor" href="#how-gnome-stays-separate" aria-label="Permalink to &quot;How GNOME stays separate&quot;">​</a></h2><p>Dependency headers, libraries and tools stay in <code>./install/deps</code>. Gnoblin&#39;s binaries link to that directory. Its library paths are not written to your shell profile or the system loader configuration. The dependency tool directory is not added to application launch paths.</p><p>The host still provides the kernel, graphics drivers, system services and compatible base libraries. The private PipeWire client connects to the existing audio service; the build does not register another PipeWire service.</p><h2 id="update" tabindex="-1">Update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;Update&quot;">​</a></h2><p>From the checkout:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ff-only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build.sh</span></span></code></pre></div><p>Preserve local changes if Git refuses the update. Log out and back in after rebuilding; configuration reload cannot replace compositor libraries.</p><h2 id="remove-the-local-session" tabindex="-1">Remove the local session <a class="header-anchor" href="#remove-the-local-session" aria-label="Permalink to &quot;Remove the local session&quot;">​</a></h2><p>Log into another session. Remove only the files created by local registration:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/systemd/user/org.gnoblin.Shell.target</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/systemd/user/org.gnoblin.Shell@wayland.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.config/systemd/user/gnome-session@gnoblin.target.d/gnoblin.conf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> daemon-reload</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/wayland-sessions/gnoblin.desktop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/share/gnome-session/sessions/gnoblin.session</span></span></code></pre></div><p>You can then remove the checkout&#39;s <code>build</code> and <code>install</code> directories. For a packaged install, use the package manager instead.</p><h2 id="missing-or-outdated-dependencies" tabindex="-1">Missing or outdated dependencies <a class="header-anchor" href="#missing-or-outdated-dependencies" aria-label="Permalink to &quot;Missing or outdated dependencies&quot;">​</a></h2><p>The build stops at a missing dependency instead of changing host packages. Keep the error and the Meson log path when reporting a build problem.</p><p>The pinned GNOME versions are in <a href="https://github.com/kierandrewett/gnoblin/blob/main/gnome-versions.json" target="_blank" rel="noreferrer">gnome-versions.json</a>. See <a href="./source-development">source development</a> for component rebuilds.</p>`,36)])])}const k=s(n,[["render",o]]);export{u as __pageData,k as default};
